from produire import produire,paras,table,steps
from medicaments import amoxicilline
parts=[
('L’otite moyenne aiguë perforée est une infection aiguë de l’oreille moyenne avec ouverture du tympan. Les {repères sémantiques} la distinguent d’une infection du conduit. Le pus peut s’écouler après une otalgie intense.',paras('L’accumulation de sécrétions dans l’oreille moyenne augmente la pression et peut perforer le tympan. La diminution de douleur lors de l’écoulement ne signifie pas que le bilan est terminé.', 'Une otorrhée à travers un aérateur transtympanique constitue un contexte distinct. Le choix thérapeutique ne se transpose pas automatiquement à une perforation spontanée.')),
('L’otite moyenne aiguë touche surtout l’enfant. Les {contextes cliniques} incluent infection respiratoire récente et épisodes antérieurs. Chez l’adulte, les données thérapeutiques sont moins abondantes.',paras('La directive suisse souligne le bénéfice plus important de l’antibiothérapie dans les formes perforées et chez les jeunes enfants avec atteinte bilatérale. Cela ne dispense pas d’évaluer gravité, contre-indications et possibilité de suivi.', 'Ne pas utiliser un taux de perforation issu d’un autre pays comme une fréquence suisse. Rechercher les facteurs de récidive et l’impact auditif.')),
('La {physiopathologie} associe inflammation, dysfonction tubaire et infection de l’oreille moyenne. La perforation permet un drainage vers le conduit. Elle n’exclut pas une extension mastoïdienne.',paras('Une infection respiratoire peut favoriser un épanchement puis une infection de l’oreille moyenne. Virus et bactéries peuvent coexister ; la présentation seule ne fournit pas un antibiogramme.', 'La membrane peut cicatriser après l’épisode. Une perforation persistante ou un écoulement récurrent nécessite une réévaluation pour maladie chronique et retentissement auditif.')),
('Les {complications urgentes} doivent être recherchées malgré l’écoulement. Mastoïdite, paralysie faciale ou signes intracrâniens imposent une évaluation hospitalière. Le nourrisson avec altération générale nécessite un bilan adapté.',paras('Douleur ou tuméfaction rétroauriculaire, rougeur et pavillon décollé évoquent une mastoïdite. Vertige important, surdité marquée, somnolence, céphalée sévère, raideur méningée ou déficit neurologique sont des alarmes.', 'Une infection sévère ne doit pas être gérée par une simple prescription différée. Chez le nouveau-né ou le jeune enfant abattu, rechercher une infection systémique et orienter selon l’état clinique.')),
('L’{interrogatoire} précise douleur puis écoulement et évolution générale. Il identifie âge, épisodes antérieurs et traitements récents. La possibilité d’une surveillance fiable participe à la décision.',paras('Demander durée, fièvre, douleur, sommeil, alimentation, hydratation et baisse auditive. Rechercher rhinopharyngite, symptômes bilatéraux, vertiges ou douleur rétroauriculaire.', 'Noter allergie aux antibiotiques, traitement dans le mois précédent, récidives, immunodépression, drains et chirurgie. Préciser si la perforation était connue avant l’épisode.')),
('L’{examen otoscopique} cherche l’origine moyenne de l’écoulement. Il s’accompagne d’un examen général et de la mastoïde. Une seule rougeur tympanique n’est pas suffisante.',paras('Observer pus, perforation et reliquats inflammatoires du tympan, avec nettoyage prudent si nécessaire. Avant perforation, le bombement et l’épanchement soutiennent l’otite moyenne aiguë.', 'Examiner le conduit, les deux oreilles, la région rétroauriculaire, l’audition et la motricité faciale selon le contexte. Contrôler température, hydratation et comportement chez l’enfant.', 'Ne pas irriguer un tympan perforé. Si la visibilité ne permet pas de localiser la cause, demander un examen spécialisé.')),
('Les {diagnostics concurrents} comprennent otite externe et maladie chronique. La durée et les antécédents aident à les distinguer. Un traumatisme ou un drain change l’interprétation.',table(['Diagnostic','Orientation'],[['Otite externe.','Conduit inflammatoire, douleur au tragus et exposition locale.'],['Otite chronique suppurée.','Perforation ancienne et écoulements récidivants.'],['Cholestéatome.','Rétraction, kératine, polype ou otorrhée persistante.'],['Perforation traumatique.','Début après choc, pression ou instrumentation.'],['Otorrhée sur drain.','Aérateur visible et antécédent de pose.']])) ,
('Le diagnostic est clinique. Les {arguments positifs} combinent histoire aiguë, inflammation de l’oreille moyenne et écoulement à travers une perforation. L’otorrhée doit être distinguée de celle d’une otite externe.',paras('Une otalgie aiguë suivie d’un écoulement purulent et d’un tympan perforé est évocatrice. Après drainage, le bombement peut avoir disparu ; l’évolution et les autres signes gardent leur valeur.', 'L’otite séromuqueuse sans inflammation aiguë n’est pas équivalente à une otite moyenne aiguë purulente. Si l’écoulement persiste, réévaluer au lieu de maintenir indéfiniment le même diagnostic.')),
('Les {examens complémentaires} ne sont pas systématiques dans une forme non compliquée. Les signes généraux et les complications guident le bilan. La persistance d’une baisse auditive justifie un contrôle.',paras('La directive suisse ne recommande pas habituellement prise de sang et microbiologie pour une otite moyenne aiguë simple. Nouveau-né, altération générale, complication ou échec constituent d’autres situations.', 'Un prélèvement ou une exploration spécialisée peut être nécessaire selon l’évolution. Une suspicion de mastoïdite ou complication intracrânienne impose avis hospitalier et imagerie selon décision spécialisée.', 'Vérifier secondairement fermeture du tympan et récupération auditive. Demander audiométrie et avis ORL si déficit, récidive ou perforation persistante.')),
('L’{algorithme} commence par les complications. L’antalgie et la décision antibiotique suivent l’évaluation clinique. Un suivi explicite doit accompagner toute stratégie.',steps('Rechercher sepsis, mastoïdite, signes neurologiques et état général inquiétant ; orienter immédiatement si présents.', 'Confirmer origine moyenne et perforation, vérifier âge, terrain, allergie, traitements récents et suivi possible.', 'Traiter la douleur et décider de l’antibiothérapie selon recommandations suisses ; la perforation augmente le bénéfice attendu.', 'Réévaluer rapidement si aggravation et selon les délais de suivi prévus ; en cas d’échec, revoir diagnostic, observance, germe et complication.', 'Contrôler résolution de l’écoulement, cicatrisation et audition ; organiser bilan ORL si persistance.')),
('L’amoxicilline est un choix de première intention lorsque l’antibiothérapie est indiquée et possible. Les {repères suisses} distinguent recommandation clinique et information de la spécialité. Les gouttes d’otite externe ne remplacent pas cette prise en charge.',paras('@@MEDICAMENTS@@')+paras('La directive suisse recommande une antibiothérapie immédiate chez l’enfant de moins de deux ans avec otite bilatérale. La perforation est un facteur de bénéfice accru ; gravité, âge et suivi déterminent la conduite, avec traitement immédiat en cas d’infection sévère.', 'La directive donne des critères d’adaptation en cas de traitement antibiotique récent, récidive ou échec ; ces situations nécessitent une nouvelle décision et ne justifient pas une substitution improvisée. Une allergie doit être caractérisée avant de choisir une alternative.', 'Ciproxin HC et Panotile sont contre-indiqués en cas de perforation. Les gouttes antalgiques destinées au tympan intact ne doivent pas être utilisées à travers une perforation.', 'Associer antalgie adaptée, conseils d’hydratation et protection de l’oreille. Les décongestionnants et antihistaminiques n’ont pas de bénéfice démontré sur les symptômes de l’otite moyenne aiguë.')),
('La {prévention des séquelles} repose sur le suivi. Une diminution de douleur ne prouve pas la fermeture du tympan. Une baisse auditive persistante mérite une évaluation.',paras('Garder l’oreille à l’abri de l’eau selon les consignes jusqu’à cicatrisation et éviter instrumentation ou lavage. Vérifier l’administration correcte et la durée de l’antibiotique choisi.', 'Expliquer aux parents les alarmes : aggravation générale, tuméfaction derrière l’oreille, somnolence ou déficit facial. Des épisodes répétés justifient un bilan et une stratégie préventive individualisée.')),
('La perforation peut soulager la douleur sans supprimer le risque de complication. L’otorrhée moyenne et l’otite externe se distinguent par l’examen. Les recommandations suisses guident la décision antibiotique. Cicatrisation et audition doivent être suivies.','')]
quiz=[('Une otalgie soulagée par du pus exclut-elle une complication ?','Non : elle peut correspondre à une perforation.'),('Toute otorrhée vient-elle de l’oreille moyenne ?','Non : le conduit et d’autres causes doivent être examinés.'),('Une otite sur drain est-elle identique à une perforation spontanée ?','Non : le contexte et le traitement peuvent différer.'),('Que suggère un pavillon décollé avec tuméfaction rétroauriculaire ?','Une mastoïdite, à évaluer en urgence.'),('Peut-on différer un avis si un déficit facial apparaît ?','Non : c’est un signe de complication.'),('Une rougeur isolée suffit-elle au diagnostic ?','Non : il faut l’ensemble clinique et les signes d’atteinte moyenne.'),('Les prélèvements sont-ils habituels dans toute forme simple ?','Non : ils dépendent du contexte et de l’évolution.'),('La perforation influence-t-elle le bénéfice antibiotique ?','Oui : les recommandations identifient un bénéfice accru dans ce groupe.'),('Quel antibiotique est proposé en première intention si indiqué et sans contre-indication ?','L’amoxicilline, avec schéma adapté et vérifié.'),('La fréquence pédiatrique SSI et celle d’Amoxi-Mepha sont-elles identiques ?','Non : deux prises dans la directive contre trois à quatre dans l’information professionnelle citée.'),('Peut-on appliquer un schéma habituel à l’insuffisance rénale ?','Non : adaptation et choix de voie doivent être vérifiés.'),('Panotile est-il compatible avec la perforation ?','Non : l’information suisse le contre-indique.'),('Les décongestionnants sont-ils utiles de routine ?','Non : leur bénéfice sur les symptômes n’est pas démontré.'),('Que contrôler après l’épisode ?','Résolution de l’écoulement, cicatrisation tympanique et récupération auditive.')]
produire(2,parts,quiz,(2,7,8,13,15,16,17,18),amoxicilline)
